parameters.inputSchema:
{
  "type": "object",
  "properties": {
    "answer": { "type": "string", "description": "The answer to the user question, in the user's language, without links" },
    "sources": {
      "type": "array",
      "description": "Web pages used for the answer, taken from the Tavily results. Empty array if no search was done",
      "items": {
        "type": "object",
        "properties": {
          "title": { "type": "string" },
          "url": { "type": "string" }
        },
        "required": ["title", "url"]
      }
    }
  },
  "required": ["answer", "sources"]
}
